@media(max-width:700px){.is-mobile .research-home.markdown-preview-view,.markdown-preview-view.research-home{padding-inline:8px!important}.research-home .rd-activity-stats{gap:6px}.research-home .rd-activity-stats span{font-size:12px}.research-home .rd-module .rd-activity-grid{gap:2px}.research-home .rd-module .rd-activity>.rd-small{font-size:12px}.research-home .rd-module .rd-task-row input[type=checkbox]{width:22px;height:22px;position:relative}.rd-module .rd-plan-top select,.rd-module .rd-plan-period select{font-size:15px!important}}
