.rd-desktop-card[data-card=graph] .rd-graph-map{flex:none;height:145px;min-height:145px;}
.rd-desktop-card[data-card=graph] .rd-graph-node.is-compact{width:20px;max-width:20px;height:20px;min-height:20px;font-size:10px;}
.rd-graph-documents{flex:none;margin:4px 0;}
.rd-graph-documents summary{cursor:pointer;font-size:12px;min-height:28px;line-height:28px;}
@container(min-width:1051px){.rd-desktop-grid{grid-template-rows:minmax(0,180fr) minmax(0,160fr) minmax(0,105fr) minmax(0,105fr) minmax(0,235fr);}}

/* A quiet constellation: document nodes, real links, one readable selection. */
.rd-module[data-module=graph] .rd-body{gap:6px;overflow:hidden;}
.rd-module[data-module=graph] .rd-module-heading{gap:7px;}
.rd-module[data-module=graph] .rd-graph-picker{min-width:80px;max-width:100px;}
.rd-module .rd-network-expand{width:30px;min-width:30px;height:30px;min-height:30px;padding:6px!important;border:0;box-shadow:none;background:transparent;}
.rd-network-expand svg{width:16px;height:16px;}
.rd-network-map{position:relative;flex:1 1 auto;min-height:90px;max-height:260px;isolation:isolate;background:radial-gradient(ellipse at center,rgba(255,255,255,.68),transparent 70%);}
.rd-network-map>svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;}
.rd-network-map path{fill:none;stroke:#bcb7cf;stroke-width:.7;opacity:.42;transition:opacity 160ms ease,stroke 160ms ease;}
.rd-network-map path.is-active{stroke:#7a91a7;stroke-width:1;opacity:.65;}
.rd-module .rd-network-node{position:absolute;transform:translate(-50%,-50%);display:grid;place-items:center;width:28px!important;min-width:28px!important;max-width:none;height:28px!important;min-height:28px!important;padding:0!important;margin:0;border:0!important;background:transparent!important;box-shadow:none!important;border-radius:50%;}
.rd-network-dot{width:10px;height:10px;border-radius:50%;background:#609b91;border:2px solid rgba(255,255,255,.9);box-shadow:0 1px 4px rgba(37,66,65,.16);transition:transform 160ms ease,box-shadow 160ms ease;}
.is-project>.rd-network-dot{background:#b79a58;}.is-meeting>.rd-network-dot{background:#947bad;}
.rd-network-node[aria-pressed=true]>.rd-network-dot,.rd-network-node:hover>.rd-network-dot{transform:scale(1.4);box-shadow:0 0 0 4px rgba(100,155,143,.15);}
.rd-module .rd-network-node.is-hub{width:44px!important;height:44px!important;min-width:44px!important;min-height:44px!important;}
.is-hub>.rd-network-dot{display:grid;place-items:center;width:30px;height:30px;background:#fff;color:#48766f;border:1px solid #d3dfd9;box-shadow:0 3px 10px rgba(48,65,75,.10);}.is-hub>.rd-network-dot svg{width:15px;height:15px;}
.rd-module .rd-network-caption{flex:0 0 auto;display:grid;grid-template-columns:1fr 20px;gap:2px 8px;width:100%;min-height:52px;padding:9px 12px!important;text-align:left;border:1px solid rgba(132,124,155,.12);border-radius:12px;background:rgba(255,255,255,.68);box-shadow:none;}
.rd-network-kind{font-size:10px;font-weight:500;color:#747182;grid-column:1;}.rd-network-title{font-size:12px;line-height:1.45;font-weight:600;color:#384e49;grid-column:1;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;}.rd-network-arrow{grid-column:2;grid-row:1/3;align-self:center;color:#6b857f;}.rd-network-arrow svg{width:16px;height:16px;}
.rd-network-node:focus-visible,.rd-network-caption:focus-visible{outline:2px solid #507eab!important;outline-offset:2px;}
.research-home .rd-network-map{height:200px;min-height:180px;flex:none;}.research-home .rd-network-title{font-size:14px;}.research-home .rd-network-kind{font-size:12px;}
@media(prefers-reduced-motion:reduce){.rd-network-dot,.rd-network-map path{transition:none;}}

.rd-module[data-module=projects] .rd-module-heading h2{display:none;}
.rd-module[data-module=projects] .rd-module-heading{gap:8px;}
.rd-module[data-module=projects] .rd-module-heading .rd-project-picker{flex:1;min-width:0;width:auto;max-width:100%;margin:0;font-size:14px!important;font-weight:700;text-align:left;text-align-last:left;padding-left:10px!important;padding-right:28px!important;height:36px;}
.rd-module[data-module=projects] .rd-module-heading .rd-new-project-button{flex:0 0 36px;width:36px;min-width:36px;height:36px;min-height:36px;padding:0!important;font-size:24px;line-height:1;border-radius:10px;}
.research-home .rd-module[data-module=projects] .rd-module-heading .rd-new-project-button{width:44px;min-width:44px;height:44px;min-height:44px;}

.rd-module[data-module=graph] .rd-body>button.rd-network-caption{height:auto!important;min-height:56px!important;max-height:none;flex-shrink:0;grid-template-rows:auto auto;padding:8px 12px!important;}
.rd-module[data-module=graph] .rd-network-map{min-height:76px;}
.rd-network-kind{font-size:11px;line-height:1.4;}.rd-network-title{font-size:13px;line-height:1.4;}

.rd-module[data-module=projects] .rd-module-heading h2{display:block;flex:none;margin-right:0;}
.rd-project-choice{position:relative;flex:1;min-width:0;overflow:hidden;height:34px;background:rgba(255,255,255,.55);border-radius:9px;}
.rd-project-name{overflow:hidden;position:absolute;inset:0 24px 0 8px;display:flex;align-items:center;white-space:nowrap;color:#61786e;font-size:12px;font-weight:600;}
.rd-project-name>span{display:block;white-space:nowrap;width:max-content;flex:none;}
.rd-project-chevron{position:absolute;right:6px;top:10px;color:#91aaa0;}.rd-project-chevron svg{width:14px;height:14px;}
.rd-module[data-module=projects] .rd-project-choice select.rd-project-picker{position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer;}
.rd-project-choice:focus-within{outline:2px solid #507eab;outline-offset:2px;}
.rd-project-choice.is-long .rd-project-name>span{animation:rd-project-name-scroll var(--rd-name-duration,8s) ease-in-out infinite alternate;}
.rd-project-choice:hover .rd-project-name>span,.rd-project-choice:focus-within .rd-project-name>span{animation-play-state:paused;}
@keyframes rd-project-name-scroll{0%,20%{transform:translateX(0);}80%,100%{transform:translateX(var(--rd-name-travel,0));}}
@media(prefers-reduced-motion:reduce){.rd-project-choice.is-long .rd-project-name>span{animation:none;}}
.research-home .rd-project-choice{height:44px;}.research-home .rd-project-name{font-size:13px;}.research-home .rd-project-chevron{top:15px;}

/* Project heading and week selector form one compact control group. */
.rd-module[data-module=projects] .rd-module-heading{margin-bottom:4px;}
.rd-module[data-module=projects] .rd-body{padding-top:0;}
.rd-module[data-module=projects] .rd-plan-period{margin-top:0;margin-bottom:7px;}

/* Obsidian's 16px check glyph must follow the actual 20/22px input, not the theme offset. */
.rd-module .rd-task-row input[type=checkbox]::after{inset:auto!important;left:50%!important;top:50%!important;transform:translate(-50%,-50%)!important;width:100%!important;height:100%!important;margin:0!important;}

/* Paper relationship discovery: grouped topics, direct report actions. */
.rd-relation-status{font-size:11px;color:var(--text-muted);padding:0 2px 4px;flex:none;}
.rd-module .rd-relation-map{overflow:auto!important;min-height:100px!important;max-height:none;flex:1 1 auto;}
.rd-relation-plane{position:relative;width:100%;min-width:230px;isolation:isolate;}
.rd-relation-plane>svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;}
.rd-relation-band{position:absolute;left:0;right:0;border-radius:14px;background:rgba(255,255,255,.55);border:1px solid rgba(90,80,115,.09);}
.rd-relation-band>span{display:block;padding:8px 12px;font-size:12px;font-weight:600;color:#50546c;}
.rd-module .rd-relation-plane .rd-network-node{width:44px!important;height:44px!important;min-width:44px!important;min-height:44px!important;z-index:2;}
.rd-relation-plane .rd-network-dot{width:13px;height:13px;background:var(--relation-color);}
.rd-relation-plane path{stroke-dasharray:3 3;opacity:.2;}
.rd-relation-plane path.is-explicit{stroke-dasharray:none;}
.rd-relation-plane path.is-active{opacity:.9;stroke:#6976a0;stroke-width:1.4;}
.rd-relation-detail{max-height:74px;overflow:auto;flex:0 0 auto;font-size:11px;color:var(--text-muted);}
.rd-relation-disclaimer{display:block;padding:3px 2px;}
.rd-module .rd-related-paper{display:flex;flex-direction:column;align-items:stretch;text-align:left;width:100%;height:auto;min-height:44px;padding:6px 8px;margin:2px 0;background:var(--background-primary);white-space:normal;box-shadow:none;}
.rd-related-paper>span{font-size:12px;line-height:1.4;}.rd-related-paper>small{font-size:11px;color:var(--text-muted);line-height:1.4;}
.rd-relation-expanded{height:min(78vh,800px);display:flex;flex-direction:column;gap:8px;}
.rd-relation-expanded .rd-relation-detail{max-height:150px;}
.research-home .rd-relation-map{height:240px!important;min-height:240px!important;}
.theme-dark .rd-relation-band{background:rgba(160,145,190,.09);}.theme-dark .rd-relation-band>span{color:var(--text-normal);}

@container (min-width:531px) and (max-width:1050px){.rd-desktop-grid{height:auto;min-height:0;grid-template-rows:240px 350px 300px 350px 280px;}}
.rd-relation-detail[hidden]{display:none!important;}
.rd-module[data-module=graph] .rd-body>.rd-network-caption{min-height:48px!important;padding:6px 10px!important;}
.rd-module .rd-relation-map{min-height:60px!important;contain:size;}
.rd-relation-expanded .rd-relation-map{min-height:180px!important;}
